use ratatui::{prelude::*, widgets::*}; use crate::{app::App, widgets::{host_card, logo, status_bar}};
pub fn draw(f:&mut Frame, app:&App, area:Rect){ let chunks=Layout::vertical([Constraint::Length(4),Constraint::Min(5),Constraint::Length(1)]).split(area); f.render_widget(logo::block(app), chunks[0]); let cols=Layout::horizontal([Constraint::Length(22),Constraint::Percentage(43),Constraint::Percentage(57)]).split(chunks[1]); let groups=vec!["★ Favorites".to_string(),"Production".into(),"Homelab".into(),"Tailscale".into(),"Recent".into(),"All hosts".into()]; f.render_widget(List::new(groups).block(Block::bordered().border_style(app.theme.inactive_border()).title(" Groups ")).style(app.theme.normal()), cols[0]); if app.hosts.is_empty(){ let empty=Paragraph::new("No SSH hosts found.

Options:
  a  Add your first host
  i  Import from ~/.ssh/config
  ?  Help").alignment(Alignment::Center).block(Block::bordered().border_style(app.theme.border()).title(" Hosts ")); f.render_widget(empty, cols[1]); } else { let items:Vec<ListItem>=app.filtered.iter().filter_map(|i| app.hosts.get(*i)).map(|h|{ let icon=if app.ascii{"[S]"}else{"󰣀"}; let fav=if h.favorite{" "}else{""}; ListItem::new(format!("{} {}{}  {}", icon, fav, h.alias, h.hostname.clone().unwrap_or_default())) }).collect(); let mut state=ListState::default(); state.select(Some(app.selected)); let list=List::new(items).block(Block::bordered().border_style(app.theme.border()).title(" Hosts ")).highlight_style(app.theme.selected()).highlight_symbol("› "); f.render_stateful_widget(list, cols[1], &mut state); } f.render_widget(host_card::detail(app, app.current_host()), cols[2]); status_bar::draw(f, app, chunks[2], "/ search · Enter connect · s files · t tunnel · r run · h health · ? help"); }
